<?php
$uid = (int)$u['id'];
handle('group_create', function () use ($uid) { $n = trim((string)$_POST['name']); if ($n === '') throw new AppError('Give the group a name.'); $type = in_array($_POST['gtype'], ['rent', 'trip', 'restaurant', 'groceries', 'subscription', 'other'], true) ? $_POST['gtype'] : 'other';
  $gid = tx(function () use ($uid, $n, $type) { q('INSERT INTO expense_groups (name,group_type,created_by) VALUES (?,?,?)', [mb_substr($n, 0, 100), $type, $uid]); $g = (int)db()->lastInsertId(); q('INSERT INTO group_members (group_id,user_id) VALUES (?,?)', [$g, $uid]); return $g; }); flash('ok', 'Group created. Add members next.'); redirect(url('groups', ['id' => $gid])); });
$gid = (int)($_GET['id'] ?? 0);
if (!$gid) {
  $gs = rows('SELECT g.*, (SELECT COUNT(*) FROM group_members WHERE group_id=g.id) n FROM expense_groups g JOIN group_members m ON m.group_id=g.id AND m.user_id=? ORDER BY g.id DESC', [$uid]); $rows = [];
  foreach ($gs as $g) { $net = Groups::net((int)$g['id'])[$uid] ?? 0; $rows[] = ['<a href="' . e(url('groups', ['id' => $g['id']])) . '"><strong>' . e($g['name']) . '</strong></a><div class="hint">' . e(ucfirst($g['group_type'])) . '</div>', (int)$g['n'], '<span class="' . ($net < 0 ? 'neg' : ($net > 0 ? 'pos' : '')) . '">' . ($net < 0 ? 'You owe ' . e(money(dec(-$net))) : ($net > 0 ? 'You are owed ' . e(money(dec($net))) : 'Settled')) . '</span>']; }
  echo page_head('Groups', 'Share rent, trips, restaurants, groceries and subscriptions.') . '<div class="grid g-main">' . card('Your groups', tbl(['Group', 'Members', 'Your position'], $rows, 'No groups yet.')) . card('Create group', form_start('group_create') . field('Name', 'name', 'text', '', 'required maxlength="100"') . select('Type', 'gtype', ['trip' => 'Trip', 'rent' => 'Rent', 'restaurant' => 'Restaurant', 'groceries' => 'Groceries', 'subscription' => 'Subscription', 'other' => 'Other'], 'trip') . btn('Create group') . '</form>') . '</div>'; return;
}
if (!Groups::isMember($gid, $uid)) { http_response_code(403); echo card('', empty_state('You are not a member of this group.')); return; }
$g = row('SELECT * FROM expense_groups WHERE id=?', [$gid]); $mem = Groups::members($gid); $names = array_column($mem, 'name', 'id');
handle('member_add', function () use ($uid, $gid) { $x = Pay::findUser((string)$_POST['who'], $uid); if (Groups::isMember($gid, (int)$x['id'])) throw new AppError('Already a member.'); q('INSERT INTO group_members (group_id,user_id) VALUES (?,?)', [$gid, $x['id']]); notify((int)$x['id'], 'system', 'Added to group', 'You were added to ' . val('SELECT name FROM expense_groups WHERE id=?', [$gid])); return $x['name'] . ' added.'; });
handle('expense_add', function () use ($uid, $gid) { Groups::addExpense($uid, $gid, $_POST); return 'Expense added and split.'; });
handle('settle', function () use ($uid, $gid) { Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); $r = Groups::settle($uid, $gid, (int)$_POST['to'], cents($_POST['amount'] ?? ''), idem_key()); return 'Settlement sent. Reference ' . ($r['ref'] ?? ''); });
handle('gbudget_add', function () use ($uid, $gid) { $c = strtolower(trim((string)$_POST['category'])); $l = cents($_POST['limit'] ?? ''); if ($c === '' || $l <= 0) throw new AppError('Enter a category and limit.'); q('INSERT INTO budgets (user_id,group_id,category,monthly_limit) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE monthly_limit=VALUES(monthly_limit)', [$uid, $gid, $c, dec($l)]); return 'Shared budget saved.'; });
$net = Groups::net($gid); $opt = Groups::optimize($net);
echo page_head($g['name'], ucfirst($g['group_type']) . ' group &middot; ' . count($mem) . ' members', '<a class="btn secondary sm" href="' . e(url('groups')) . '">' . e(t('Back')) . '</a>');
$b = ''; foreach ($net as $id => $c) $b .= '<div class="row" style="padding:6px 0;border-top:1px solid var(--line)"><div>' . e($names[$id] ?? uname($id)) . '</div><div class="fixed ' . ($c < 0 ? 'neg' : ($c > 0 ? 'pos' : '')) . '">' . ($c > 0 ? 'is owed ' : ($c < 0 ? 'owes ' : 'settled ')) . ($c ? e(money(dec(abs($c)))) : '') . '</div></div>';
$sg = ''; foreach ($opt['transfers'] as $tr) { $mine = $tr['from'] === $uid; $sg .= '<div style="padding:10px 0;border-top:1px solid var(--line)"><strong>' . e($names[$tr['from']] ?? '?') . '</strong> pays <strong>' . e($names[$tr['to']] ?? '?') . '</strong> ' . mny(dec($tr['amount_c'])) . ($mine ? form_start('settle') . '<input type="hidden" name="to" value="' . $tr['to'] . '"><input type="hidden" name="amount" value="' . e(dec($tr['amount_c'])) . '"><div class="row" style="margin-top:6px"><input name="pin" type="password" inputmode="numeric" maxlength="6" placeholder="PIN" required aria-label="PIN" style="min-width:90px">' . btn('Pay now', 'sm') . '</div></form>' : '') . '</div>'; }
$sg = $sg ?: '<p class="muted">Everyone is settled up.</p>';
echo '<div class="grid g2">' . card('Who owes whom', $b) . card('Suggested settlements', $sg . '<p class="hint">Method: ' . e($opt['method']) . '. ' . count($opt['transfers']) . ' transfer(s) needed; without optimisation up to ' . max(0, count(array_filter($net)) - 1) . ' could be required. Finding the true minimum is NP-hard in general, so beyond 12 people a greedy method is used.</p>') . '</div><div style="height:16px"></div>';
$parts = ''; foreach ($mem as $m) $parts .= '<tr><td><label style="margin:0;font-weight:400"><input type="checkbox" name="participants[]" value="' . (int)$m['id'] . '" checked> ' . e($m['name']) . '</label></td><td data-split="custom"><input name="custom[' . (int)$m['id'] . ']" inputmode="decimal" placeholder="0.00" aria-label="Custom amount for ' . e($m['name']) . '"></td><td data-split="percent"><input name="percent[' . (int)$m['id'] . ']" inputmode="decimal" placeholder="%" aria-label="Percent for ' . e($m['name']) . '"></td></tr>';
$opts = []; foreach ($mem as $m) $opts[$m['id']] = $m['name'];
echo '<div class="grid g-main">' . card('Add an expense', form_start('expense_add') . '<div class="row">' . field('Description', 'description', 'text', '', 'required maxlength="150"') . field('Amount (BDT)', 'amount', 'text', '', 'required inputmode="decimal"') . '</div><div class="row">' . select('Paid by', 'paid_by', $opts, (string)$uid) . select('Category', 'category', ['general' => 'General', 'food' => 'Food', 'travel' => 'Travel', 'rent' => 'Rent', 'groceries' => 'Groceries', 'entertainment' => 'Entertainment'], 'general') . field('Date', 'date', 'date', date('Y-m-d')) . '</div><div class="field"><label for="split_type">Split</label><select id="split_type" name="split_type"><option value="equal">' . e(t('Equal')) . '</option><option value="custom">' . e(t('Custom')) . ' amounts</option><option value="percent">' . e(t('Percent')) . '</option></select></div><div class="table-wrap"><table><thead><tr><th>Participants</th><th data-split="custom">Amount</th><th data-split="percent">%</th></tr></thead><tbody>' . $parts . '</tbody></table></div><div style="height:12px"></div>' . btn('Add expense') . '</form>') .
 card('Members', implode('', array_map(fn($m) => '<div style="padding:4px 0">' . e($m['name']) . '</div>', $mem)) . form_start('member_add') . '<div class="row">' . field('Add member', 'who', 'text', '', 'placeholder="email or phone" required') . '<div class="fixed field"><label>&nbsp;</label>' . btn('Add', 'secondary') . '</div></div></form>') . '</div><div style="height:16px"></div>';
$ex = rows('SELECT e.*, u.name FROM group_expenses e JOIN users u ON u.id=e.paid_by WHERE e.group_id=? ORDER BY e.id DESC LIMIT 30', [$gid]); $er = [];
foreach ($ex as $e) { $sp = rows('SELECT s.share_amount, u.name FROM expense_splits s JOIN users u ON u.id=s.user_id WHERE s.expense_id=?', [$e['id']]); $er[] = [e(fdate($e['expense_date'], false)), e($e['description']) . '<div class="hint">' . e(ucfirst($e['category'])) . ' &middot; ' . e($e['split_type']) . ' split: ' . e(implode(', ', array_map(fn($s) => $s['name'] . ' ' . $s['share_amount'], $sp))) . '</div>', e($e['name']), mny($e['amount'])]; }
$st = rows('SELECT s.*, f.name fn, t.name tn FROM group_settlements s JOIN users f ON f.id=s.from_user JOIN users t ON t.id=s.to_user WHERE s.group_id=? ORDER BY s.id DESC', [$gid]); $sr = [];
foreach ($st as $s) $sr[] = [e(fdate($s['created_at'])), e($s['fn']) . ' paid ' . e($s['tn']), mny($s['amount']), ref_link((string)val('SELECT ref FROM transactions WHERE id=?', [$s['txn_id']]))];
$bs = array_filter(Cash::budgetStatus($uid), fn($x) => (int)$x['group_id'] === $gid); $bb = '';
foreach ($bs as $x) { $pct = 100 * (float)$x['spent'] / max(0.01, (float)$x['monthly_limit']); $bb .= '<div style="margin-bottom:10px"><strong>' . e(ucfirst($x['category'])) . '</strong> ' . mny($x['spent']) . ' of ' . mny($x['monthly_limit']) . progress($pct, $pct >= 100 ? 'bad' : ($pct >= 80 ? 'warn' : '')) . '</div>'; }
echo card('Expenses', tbl(['Date', 'What', 'Paid by', ['Amount', 'num']], $er, 'No expenses yet.')) . '<div style="height:16px"></div><div class="grid g2">' . card('Settlement history', tbl(['When', 'Who', ['Amount', 'num'], 'Ref'], $sr, 'No settlements yet.')) . card('Shared budgets (this month)', $bb . form_start('gbudget_add') . '<div class="row">' . field('Category', 'category', 'text', 'travel', 'required') . field('Monthly limit', 'limit', 'text', '', 'required inputmode="decimal"') . '<div class="fixed field"><label>&nbsp;</label>' . btn('Save', 'secondary') . '</div></div></form>') . '</div>';
